// Independent span cross-check: JS strings are indexed in UTF-16 code units,
// so text.slice(start, end) is the same arithmetic the platform re-read uses.
// This shares no code with the Python verifier.
import { readFileSync } from "node:fs";
const d = JSON.parse(readFileSync("engine-input.json", "utf8"));
let n = 0, bad = 0;
for (const s of d.subjects) {
  for (const f of s.facts) {
    n++;
    const text = d.documents[f.documentId].text;
    const seg = text.slice(f.start, f.end);
    const okSpan = seg === f.quote;
    const okSurface = f.quote.includes(f.surface);
    const okMirror = f.source.start === f.start && f.source.end === f.end && f.source.quote === f.quote;
    if (!(okSpan && okSurface && okMirror)) { bad++; console.log("FAIL", f.documentId, f.variable, JSON.stringify({seg, quote: f.quote})); }
    else console.log("ok", f.documentId, `[${f.start},${f.end})`, f.variable, f.polarity, JSON.stringify(seg));
  }
}
console.log(`facts=${n} failed=${bad}`);
process.exit(bad === 0 && n > 0 ? 0 : 1);
